module top_module (
    input clk,
    input a, 
    output reg q
);
    always @(posedge clk) begin
        if (a == 1'b1) begin
            q <= ~q;
        end else begin
            q <= q;
        end
    end
endmodule

module top_module (
    input clk,
    input areset,
    input x,
    output reg z
);

    parameter IDLE = 0;
    parameter CONVERTING = 1;

    reg [31:0] shift_reg;
    reg [31:0] result;
    reg [31:0] count;
    reg [1:0] state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= IDLE;
            shift_reg <= 0;
            result <= 0;
            count <= 0;
            z <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (!x) begin
                        state <= CONVERTING;
                        shift_reg <= 0;
                        result <= 0;
                        count <= 0;
                    end
                end
                CONVERTING: begin
                    shift_reg <= {shift_reg[30:0], x};
                    count <= count + 1;
                    if (count == 32) begin
                        state <= IDLE;
                        result <= ~shift_reg + 1;
                        z <= result[31];
                    end
                end
            endcase
        end
    end

endmodule

module top_module (
    input clk,
    input areset,
    input x,
    output reg z
);

reg [31:0] shift_reg;
reg [31:0] result;
reg sign_bit;
reg done;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        shift_reg <= 0;
        result <= 0;
        sign_bit <= 0;
        done <= 1;
        z <= 0;
    end else begin
        if (!done) begin
            shift_reg = {shift_reg[30:0], x};
            if (shift_reg == 32'b0) begin
                result = 0;
                done = 1;
            end else if (shift_reg[31]) begin
                result = ~shift_reg + 1;
                done = 1;
            end else begin
                result = shift_reg;
                done = 1;
            end
        end
        z <= result;
    end
end

endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output reg [23:0] out_bytes,
    output reg done
);
    parameter STATE_IDLE = 2'b00;
    parameter STATE_WAIT_1 = 2'b01;
    parameter STATE_WAIT_2 = 2'b10;

    reg [1:0] state;
    reg [2:0] byte_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= STATE_IDLE;
            byte_count <= 3'b000;
            out_bytes <= 24'b0;
            done <= 1'b0;
        end else begin
            case (state)
                STATE_IDLE: begin
                    if (in[3]) begin
                        state <= STATE_WAIT_1;
                        byte_count <= 3'b001;
                        out_bytes <= {in, 8'b0};
                    end
                end
                STATE_WAIT_1: begin
                    if (byte_count < 3'b110) begin
                        state <= STATE_WAIT_1;
                        byte_count <= byte_count + 1;
                        out_bytes <= {out_bytes[15:0], in};
                    end else begin
                        state <= STATE_WAIT_2;
                        byte_count <= 3'b001;
                        out_bytes <= {out_bytes[15:0], in};
                    end
                end
                STATE_WAIT_2: begin
                    if (byte_count < 3'b111) begin
                        state <= STATE_WAIT_2;
                        byte_count <= byte_count + 1;
                        out_bytes <= {out_bytes[7:0], in};
                    end else begin
                        state <= STATE_IDLE;
                        byte_count <= 3'b000;
                        out_bytes <= 24'b0;
                        done <= 1'b1;
                    end
                end
                default: state <= STATE_IDLE;
            endcase
        end
    end
endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output reg [23:0] out_bytes,
    output reg done
);
    parameter STATE_IDLE = 2'b00;
    parameter STATE_WAIT_1 = 2'b01;
    parameter STATE_WAIT_2 = 2'b10;

    reg [1:0] state;
    reg [7:0] byte1, byte2, byte3;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= STATE_IDLE;
            byte1 <= 8'd0;
            byte2 <= 8'd0;
            byte3 <= 8'd0;
            out_bytes <= 24'd0;
            done <= 1'b0;
        end else begin
            case (state)
                STATE_IDLE: begin
                    if (in[3]) begin
                        state <= STATE_WAIT_1;
                        byte1 <= in;
                    end
                end
                STATE_WAIT_1: begin
                    state <= STATE_WAIT_2;
                    byte2 <= in;
                end
                STATE_WAIT_2: begin
                    state <= STATE_IDLE;
                    byte3 <= in;
                    out_bytes <= {byte1, byte2, byte3};
                    done <= 1'b1;
                end
                default: begin
                    state <= STATE_IDLE;
                end
            endcase
        end
    end
endmodule

module top_module (
	input [5:0] y,
	input w,
	output reg Y1,
	output reg Y3
);
	always @(posedge w) begin
		if (y == 6'b000001) begin // State A
			Y1 <= 1'b0;
			Y3 <= 1'b0;
		end else if (y == 6'b000010) begin // State B
			Y1 <= 1'b1;
			Y3 <= 1'b0;
		end else if (y == 6'b000100) begin // State C
			Y1 <= 1'b0;
			Y3 <= 1'b1;
		end else if (y == 6'b001000) begin // State D
			Y1 <= 1'b0;
			Y3 <= 1'b0;
		end else if (y == 6'b010000) begin // State E
			Y1 <= 1'b1;
			Y3 <= 1'b0;
		end else if (y == 6'b100000) begin // State F
			Y1 <= 1'b0;
			Y3 <= 1'b1;
		end
	end
endmodule

