module top_module (
	input [6:1] y,
	input w,
	output reg Y2,
	output reg Y4
);
	always_comb begin
		case(y)
			7'b000001: begin // State A
				Y2 = 1'b0;
				if (w == 1'b0) Y4 = 1'b0;
				else Y4 = 1'b1;
			end
			7'b000010: begin // State B
				Y2 = 1'b1;
				if (w == 1'b0) Y4 = 1'b0;
				else Y4 = 1'b1;
			end
			7'b000100: begin // State C
				Y2 = 1'b0;
				if (w == 1'b0) Y4 = 1'b1;
				else Y4 = 1'b0;
			end
			7'b001000: begin // State D
				Y2 = 1'b1;
				if (w == 1'b0) Y4 = 1'b0;
				else Y4 = 1'b1;
			end
			7'b010000: begin // State E
				Y2 = 1'b1;
				if (w == 1'b0) Y4 = 1'b1;
				else Y4 = 1'b0;
			end
			7'b100000: begin // State F
				Y2 = 1'b0;
				if (w == 1'b0) Y4 = 1'b1;
				else Y4 = 1'b0;
			end
			default: begin
				Y2 = 1'b0;
				Y4 = 1'b0;
			end
		endcase
	end
endmodule

module top_module (
    input clk,
    input x,
    output z
);

reg [1:0] dffs;
wire xor_out, and_out, or_out;

assign xor_out = x ^ dffs[0];
assign and_out = x & ~dffs[1];
assign or_out = x | ~dffs[2];

always @(posedge clk) begin
    dffs <= {xor_out, and_out, or_out};
end

assign z = ~(dffs[0] ^ dffs[1] ^ dffs[2]);

endmodule

