module top_module(
    input clk,
    input load,
    input [511:0] data,
    output reg [511:0] q
);
    reg [511:0] q_reg;

    always @(posedge clk) begin
        if (load) begin
            q_reg = data;
        end else begin
            q_reg[0] = q[511];
            q_reg[511] = q[0];
            for (int i = 1; i < 511; i++) begin
                q_reg[i] = q[i-1] ^ q[i+1] ^ q[i];
            end
        end
    end

    assign q = q_reg;
endmodule

module top_module(
    input clk,
    input load,
    input [511:0] data,
    output reg [511:0] q
);
    reg [511:0] q_reg;

    always @(posedge clk) begin
        if (load) begin
            q_reg = data;
        end else begin
            q_reg[0] <= 0; // Boundary condition
            for (int i = 1; i < 511; i++) begin
                q_reg[i] <= q_reg[i-1] ^ q_reg[i+1];
            end
            q_reg[511] <= 0; // Boundary condition
        end
    end

    assign q = q_reg;
endmodule

module top_module(
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);
    reg [31:0] prev_in;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out <= 32'b0;
            prev_in <= 32'b0;
        end else begin
            prev_in <= in;
            for (int i = 0; i < 32; i++) begin
                if (prev_in[i] == 1 && in[i] == 0)
                    out[i] <= 1;
                else
                    out[i] <= 0;
            end
        end
    end
endmodule

module top_module(
    input clk,
    input reset,
    input [31:0] in,
    output reg [31:0] out
);
    reg [31:0] prev_in;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            out <= 32'b0;
            prev_in <= 32'b0;
        end else begin
            prev_in <= in;
            out <= (in & ~prev_in) | out;
        end
    end
endmodule

module top_module(
    input clk,
    input areset,
    input train_valid,
    input train_taken,
    output logic [1:0] state
);
    logic [1:0] counter;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            counter <= 2'b01; // Weakly not-taken
        end else if (train_valid) begin
            if (train_taken) begin
                counter <= (counter == 2'b11) ? counter : counter + 1;
            end else begin
                counter <= (counter == 2'b00) ? counter : counter - 1;
            end
        end else begin
            counter <= counter;
        end
    end

    assign state = counter;
endmodule

module top_module (
    input [7:0] in,
    output reg [2:0] pos
);
    always @(in) begin
        pos = 3'b100; // Initialize to 4 (since we need to count from 0)
        if (in[0]) pos = 3'b000;
        else if (in[1]) pos = 3'b001;
        else if (in[2]) pos = 3'b010;
        else if (in[3]) pos = 3'b011;
        else if (in[4]) pos = 3'b100;
        else if (in[5]) pos = 3'b101;
        else if (in[6]) pos = 3'b110;
        else if (in[7]) pos = 3'b111;
    end
endmodule

module top_module
(
    input clk,
    input areset,
    input predict_valid,
    input predict_taken,
    output logic [31:0] predict_history,

    input train_mispredicted,
    input train_taken,
    input [31:0] train_history
);
    logic [31:0] history_reg;
    logic [31:0] next_history;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            history_reg <= 32'b0;
        end else begin
            if (train_mispredicted) begin
                // Load the history after the completion of the mispredicted branch
                history_reg <= {train_history, train_taken};
            end else if (predict_valid) begin
                // Shift in predict_taken from the LSB side
                next_history = {history_reg[30:0], predict_taken};
                history_reg <= next_history;
            end
        end
    end

    assign predict_history = history_reg;
endmodule

module top_module
(
    input clk,
    input areset,
    input predict_valid,
    input predict_taken,
    output logic [31:0] predict_history,

    input train_mispredicted,
    input train_taken,
    input [31:0] train_history
);
    logic [31:0] history_reg;

    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            history_reg <= 32'b0;
        end else if (train_mispredicted) begin
            history_reg <= {train_history, train_taken};
        end else if (predict_valid) begin
            history_reg <= {history_reg[30:0], predict_taken};
        end
    end

    assign predict_history = history_reg;
endmodule

module top_module(
    input mode,
    input too_cold, 
    input too_hot,
    input fan_on,
    output heater,
    output aircon,
    output fan
);
    // Internal signals
    reg heater_reg;
    reg aircon_reg;
    reg fan_reg;

    always @(posedge mode or posedge too_cold or posedge too_hot or posedge fan_on) begin
        if (mode == 1) begin // Heating mode
            heater_reg <= too_cold;
            aircon_reg <= 0;
        end else if (mode == 0) begin // Cooling mode
            heater_reg <= 0;
            aircon_reg <= too_hot;
        end

        fan_reg <= heater_reg | aircon_reg | fan_on;
    end

    assign heater = heater_reg;
    assign aircon = aircon_reg;
    assign fan = fan_reg;
endmodule

module top_module(
	input mode,
	input too_cold, 
	input too_hot,
	input fan_on,
	output reg heater,
	output reg aircon,
	output reg fan
);
	always @(posedge mode or posedge too_cold or posedge too_hot or posedge fan_on)
	begin
		if (mode == 1) // Heating mode
		begin
			heater = too_cold;
			aircon = 0;
			fan = 1;
		end
		else if (mode == 0) // Cooling mode
		begin
			heater = 0;
			aircon = too_hot;
			fan = 1;
		end
		else
		begin
			heater = 0;
			aircon = 0;
			fan = 0;
		end

		if (fan_on)
			fan = 1;
	end
endmodule

module top_module (
	input a,
	input b,
	input c,
	input d,
	output reg out_sop,
	output reg out_pos
);
reg [3:0] input_value;

always @(*) begin
	input_value = {d, c, b, a};
	case(input_value)
		2, 7, 15: out_sop = 1;
		default: out_sop = 0;
	endcase
end

assign out_pos = ~out_sop;

endmodule

