module top_module (
	input clk,
	input x,
	input [2:0] y,
	output reg Y0,
	output reg z
);
reg [2:0] next_y;

always @(posedge clk) begin
	case (y)
		3'b000: next_y = x ? 3'b010 : 3'b001;
		3'b001: next_y = x ? 3'b100 : 3'b001;
