parameter A = 2'b00, B = 2'b01, C = 2'b10, D = 2'b11;

always @(posedge clk or negedge resetn) begin
    if (!resetn)
        state <= A;
    else
        state <= next_state;
end

always @(*) begin
    next_state = state;
    g = 4'b0000;

    case (state)
        A: begin
            if (r == 4'b0000)
                next_state = A;
            else if (r == 4'b0001)
                next_state = B;
            else if (r == 4'b0010)
                next_state = C;
            else if (r == 4'b0011)
                next_state = D;
        end
        B: begin
            if (r == 4'b0001 && g[1])
                next_state = B;
            else
                next_state = A;
        end
        C: begin
            if (r == 4'b0010 && g[2])
                next_state = C;
            else
                next_state = A;
        end
        D: begin
            next_state = A;
        end
        default: next_state = A;
    endcase

    case (state)
        A: begin
            if (r == 4'b0001)
                g[1] = 1;
            else if (r == 4'b0010)
                g[2] = 1;
            else if (r == 4'b0011)
                g[3] = 1;
        end
        B: begin
            if (r == 4'b0001)
                g[1] = 1;
        end
        C: begin
            if (r == 4'b0010)
                g[2] = 1;
        end
        default: ;
    endcase
end

endmodule

module top_module (
    input clk,
    input resetn,
    input [3:1] r,
    output reg [3:1] g
);

    // State definitions
    localparam A = 4'b0000;
    localparam B = 4'b0001;
    localparam C = 4'b0010;
    localparam D = 4'b0011;

    reg [1:0] state, next_state;

    // State register
    always @(posedge clk or negedge resetn) begin
        if (!resetn)
            state <= A;
        else
            state <= next_state;
    end

    // Next state logic
    always @(*) begin
        next_state = state;
        case (state)
            A: begin
                if (r == 4'b0000)
                    next_state = A;
                else if (r[1] == 1'b1)
                    next_state = B;
                else if (r[2] == 1'b1)
                    next_state = C;
                else if (r[3] == 1'b1)
                    next_state = D;
            end
            B: begin
                if (g[1] == 1'b1 && r[1] == 1'b1)
                    next_state = B;
                else if (g[1] == 1'b1 && r[1] == 1'b0)
                    next_state = A;
            end
            C: begin
                if (g[2] == 1'b1 && r[2] == 1'b1)
                    next_state = C;
                else if (g[2] == 1'b1 && r[2] == 1'b0)
                    next_state = A;
            end
            D: begin
                next_state = A; // Device 3 has the lowest priority
            end
            default: next_state = A;
        endcase
    end

    // Output logic
    always @(*) begin
        g = 4'b0000;
        case (state)
            A: begin
                if (r[1] == 1'b1)
                    g[1] = 1'b1;
                else if (r[2] == 1'b1)
                    g[2] = 1'b1;
                else if (r[3] == 1'b1)
                    g[3] = 1'b1;
            end
            B: g[1] = 1'b1;
            C: g[2] = 1'b1;
            D: g[3] = 1'b1;
        endcase
    end

endmodule

