				if (byte_count == 3'b010) begin
					state <= RECEIVE_BYTES;
					byte_count <= 3'b001;
				end else if (!in[3]) begin
					state <= IDLE;
				end
			end
			RECEIVE_BYTES: begin
				if (byte_count == 3'b100) begin
					state <= IDLE;
					done <= 1'b1;
