            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                    end else begin
                        state <= COUNT_1;
                        count <= 3'b001;
                    end
                end
                COUNT_1: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_1;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_2;
                        count <= 3'b001;
                    end
                end
                COUNT_2: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_2;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_3;
                        count <= 3'b001;
                    end
                end
                COUNT_3: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_3;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_4;
                        count <= 3'b001;
                    end
                end
                COUNT_4: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_4;
                        count <= count + 1;
                    end else begin
                        state <= COUNT_5;
                        count <= 3'b001;
                    end
                end
                COUNT_5: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else if (count < 5) begin
                        state <= COUNT_5;
                        count <= count + 1;
                    end else begin
                        state <= FLAG;
                        count <= 3'b000;
                    end
                end
                FLAG: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count <= 3'b000;
                    end else begin
                        state <= FLAG;
                    end
                end
                default: begin
                    state <= IDLE;
                    count <= 3'b000;
                end
            endcase

            // Output logic
            disc <= (state == COUNT_5);
            flag <= (state == FLAG);
            err <= (count >= 6);
        end
    end
endmodule

module top_module (
    input clk,
    input reset,
    input in,
    output reg disc,
    output reg flag,
    output reg err
);

    // State definitions
    localparam IDLE = 3'b000;
    localparam COUNT_1S = 3'b001;
    localparam FLAG = 3'b010;
    localparam ERROR = 3'b011;

    // Internal signals
    reg [2:0] state;
    reg [2:0] count_ones;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            count_ones <= 3'b000;
            disc <= 1'b0;
            flag <= 1'b0;
            err <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                    end else begin
                        state <= COUNT_1S;
                        count_ones <= 3'b001;
                    end
                    disc <= 1'b0;
                    flag <= 1'b0;
                    err <= 1'b0;
                end
                COUNT_1S: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count_ones <= 3'b000;
                    end else begin
                        if (count_ones == 3'b111) begin
                            state <= ERROR;
                        end else if (count_ones == 3'b110) begin
                            state <= FLAG;
                        end else begin
                            state <= COUNT_1S;
                            count_ones <= count_ones + 1;
                        end
                    end
                    disc <= 1'b0;
                    flag <= 1'b0;
                    err <= 1'b0;
                end
                FLAG: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count_ones <= 3'b000;
                    end else begin
                        state <= COUNT_1S;
                        count_ones <= 3'b001;
                    end
                    disc <= 1'b0;
                    flag <= 1'b1;
                    err <= 1'b0;
                end
                ERROR: begin
                    if (in == 1'b0) begin
                        state <= IDLE;
                        count_ones <= 3'b000;
                    end else begin
                        state <= COUNT_1S;
                        count_ones <= 3'b001;
                    end
                    disc <= 1'b0;
                    flag <= 1'b0;
                    err <= 1'b1;
                end
                default: begin
                    state <= IDLE;
                    count_ones <= 3'b000;
                    disc <= 1'b0;
                    flag <= 1'b0;
                    err <= 1'b0;
                end
            endcase
        end
    end

