module top_module (
    input clk,
    input reset,
    input [3:1] s,
    output reg fr3,
    output reg fr2,
    output reg fr1,
    output reg dfr
);

reg [1:0] state;
reg [1:0] prev_state;

parameter STATE_NONE = 2'b00;
parameter STATE_BETWEEN_S3_S2 = 2'b01;
parameter STATE_BETWEEN_S2_S1 = 2'b10;
parameter STATE_BELOW_S1 = 2'b11;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        state <= STATE_BELOW_S1;
        prev_state <= STATE_BELOW_S1;
        fr3 <= 1;
        fr2 <= 1;
        fr1 <= 1;
        dfr <= 0;
    end else begin
        prev_state <= state;
        case (s)
            4'b1111: state <= STATE_NONE;
            4'b0111: state <= STATE_BETWEEN_S3_S2;
            4'b0011: state <= STATE_BETWEEN_S2_S1;
            default: state <= STATE_BELOW_S1;
        endcase

        case ({state, prev_state})
            {STATE_NONE, STATE_NONE}, {STATE_NONE, STATE_BETWEEN_S3_S2}, {STATE_NONE, STATE_BETWEEN_S2_S1}, {STATE_NONE, STATE_BELOW_S1}: begin
                fr3 <= 1;
                fr2 <= 1;
                fr1 <= 1;
                dfr <= 0;
            end
            {STATE_BETWEEN_S3_S2, STATE_NONE}, {STATE_BETWEEN_S3_S2, STATE_BETWEEN_S3_S2}, {STATE_BETWEEN_S3_S2, STATE_BETWEEN_S2_S1}, {STATE_BETWEEN_S3_S2, STATE_BELOW_S1}: begin
                fr3 <= 0;
                fr2 <= 0;
                fr1 <= 1;
                dfr <= 0;
            end
            {STATE_BETWEEN_S2_S1, STATE_NONE}, {STATE_BETWEEN_S2_S1, STATE_BETWEEN_S3_S2}, {STATE_BETWEEN_S2_S1, STATE_BETWEEN_S2_S1}, {STATE_BETWEEN_S2_S1, STATE_BELOW_S1}: begin
                fr3 <= 0;
                fr2 <= 1;
                fr1 <= 1;
                dfr <= 1;
            end
            {STATE_BELOW_S1, STATE_NONE}, {STATE_BELOW_S1, STATE_BETWEEN_S3_S2}, {STATE_BELOW_S1, STATE_BETWEEN_S2_S1}, {STATE_BELOW_S1, STATE_BELOW_S1}: begin
                fr3 <= 0;
                fr2 <= 1;
                fr1 <= 1;
                dfr <= 1;
            end
        endcase
    end
end

endmodule

module top_module (
    input clk,
    input in,
    input reset,
    output reg done
);

    // States
    localparam IDLE = 2'b00;
    localparam START_BIT = 2'b01;
    localparam DATA_BITS = 2'b10;
    localparam STOP_BIT = 2'b11;

    // State register
    reg [1:0] state;

    // Data register
    reg [7:0] data_reg;

    // Bit counter
    reg [2:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            data_reg <= 8'b0;
            bit_count <= 3'b0;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= START_BIT;
                        bit_count <= 3'b0;
                    end
                end
                START_BIT: begin
                    if (bit_count == 3'b0) begin
                        state <= DATA_BITS;
                    end else begin
                        bit_count <= bit_count + 1;
                    end
                end
                DATA_BITS: begin
                    if (bit_count < 3'b1000) begin
                        data_reg[bit_count] <= in;
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP_BIT;
                    end
                end
                STOP_BIT: begin
                    if (in == 1'b1) begin
                        state <= IDLE;
                        done <= 1'b1;
                    end else begin
                        state <= START_BIT;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

endmodule

module top_module (
	input clk,
	input in,
	input reset,
	output reg done
);

typedef enum reg [2:0] {IDLE, START_BIT, DATA_BITS, STOP_BIT} state_t;
state_t current_state, next_state;

reg [7:0] data_reg;
integer bit_count;

always @(posedge clk or posedge reset) begin
	if (reset)
		current_state <= IDLE;
	else
		current_state <= next_state;
end

always @(*) begin
	next_state = current_state;
	done = 0;
	case (current_state)
		IDLE: begin
			data_reg = 8'b0;
			bit_count = 0;
			if (in == 0) begin
				next_state = START_BIT;
			end
		end
		START_BIT: begin
			if (bit_count == 0 && in == 0) begin
				next_state = DATA_BITS;
			end else if (bit_count != 0 || in != 0) begin
				next_state = IDLE;
			end
		end
		DATA_BITS: begin
			if (bit_count < 7) begin
				data_reg[bit_count] = in;
				next_state = DATA_BITS;
				bit_count++;
			end else if (bit_count == 7) begin
				data_reg[bit_count] = in;
				next_state = STOP_BIT;
				bit_count++;
			end
		end
		STOP_BIT: begin
			if (in == 1) begin
				done = 1;
				next_state = IDLE;
			end else if (in == 0) begin
				next_state = STOP_BIT;
			end
		end
	default: begin
		next_state = IDLE;
	end
	endcase
end

endmodule

module top_module (
    input clk,
    input in,
    input reset,
    output reg [7:0] out_byte,
    output reg done
);
    parameter IDLE = 2'b00;
    parameter START_BIT = 2'b01;
    parameter DATA_BITS = 2'b10;
    parameter STOP_BIT = 2'b11;

    reg [1:0] state;
    reg [2:0] bit_count;
    reg [7:0] received_byte;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            bit_count <= 3'b000;
            received_byte <= 8'b00000000;
            out_byte <= 8'b00000000;
            done <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (in == 1'b0) begin
                        state <= START_BIT;
                        bit_count <= 3'b000;
                        received_byte <= 8'b00000000;
                    end
                end
                START_BIT: begin
                    if (bit_count == 3'b000) begin
                        if (in == 1'b0) begin
                            state <= DATA_BITS;
                        end else begin
                            state <= IDLE;
                        end
                    end else begin
                        bit_count <= bit_count + 1;
                    end
                end
                DATA_BITS: begin
                    if (bit_count < 3'b100) begin
                        received_byte[bit_count] <= in;
                        bit_count <= bit_count + 1;
                    end else begin
                        state <= STOP_BIT;
                    end
                end
                STOP_BIT: begin
                    if (in == 1'b1) begin
                        out_byte <= received_byte;
                        done <= 1'b1;
                        state <= IDLE;
                    end else begin
                        state <= STOP_BIT;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end
endmodule

