module top_module(
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss
);

reg [3:0] bcd_ss;
reg [3:0] bcd_mm;
reg [3:0] bcd_hh;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        pm <= 0;
        bcd_ss <= 8'd0;
        bcd_mm <= 8'd0;
        bcd_hh <= 8'd12;
    end else begin
        if (ena) begin
            bcd_ss <= bcd_ss + 1;
            if (bcd_ss == 8'd60) begin
                bcd_ss <= 8'd0;
                bcd_mm <= bcd_mm + 1;
                if (bcd_mm == 8'd60) begin
                    bcd_mm <= 8'd0;
                    bcd_hh <= bcd_hh + 1;
                    if (bcd_hh == 8'd13) begin
                        bcd_hh <= 8'd1;
                    end
                end
            end
        end
    end
end

always @(*) begin
    if (bcd_hh > 8'd12) begin
        pm = 1;
        hh = {4'b0, bcd_hh - 8'd12};
    end else begin
        pm = 0;
        hh = {4'b0, bcd_hh};
    end
    mm = {4'b0, bcd_mm};
    ss = {4'b0, bcd_ss};
end

endmodule

module top_module(
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss
);

reg [3:0] sec_cnt;
reg [3:0] min_cnt;
reg [3:0] hr_cnt;

always @(posedge clk or posedge reset) begin
    if (reset) begin
        sec_cnt <= 4'b0000;
        min_cnt <= 4'b0000;
        hr_cnt <= 4'b0000;
        pm <= 1'b0;
        hh <= 8'b00001000; // 12 in BCD
        mm <= 8'b00000000; // 00 in BCD
        ss <= 8'b00000000; // 00 in BCD
    end else if (ena) begin
        sec_cnt <= sec_cnt + 1;
        if (sec_cnt == 4'b1111) begin
            sec_cnt <= 4'b0000;
            min_cnt <= min_cnt + 1;
            if (min_cnt == 4'b1111) begin
                min_cnt <= 4'b0000;
                hr_cnt <= hr_cnt + 1;
                if (hr_cnt == 4'b1111) begin
                    hr_cnt <= 4'b0000;
                    pm <= ~pm;
                end
            end
        end
    end
