module top_module (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);

    // State definitions
    localparam IDLE = 2'b00;
    localparam WALK_LEFT = 2'b01;
    localparam WALK_RIGHT = 2'b10;

    // Current state and next state
    reg [1:0] current_state, next_state;

    // Internal signals
    reg fall;

    // State transition logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            fall <= 0;
        end else begin
            current_state <= next_state;
            fall <= ground ? 0 : fall;
        end
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                if (fall) begin
                    next_state = IDLE; // Stay in IDLE if falling
                end else if (bump_left || bump_right) begin
                    next_state = WALK_RIGHT; // Switch to walking right
                end else begin
                    next_state = WALK_LEFT; // Continue walking left
                end
            end
            WALK_LEFT: begin
                if (fall) begin
                    next_state = IDLE; // Stay in IDLE if falling
                end else if (bump_left || bump_right) begin
                    next_state = WALK_RIGHT; // Switch to walking right
                end else begin
                    next_state = WALK_LEFT; // Continue walking left
                end
            end
            WALK_RIGHT: begin
                if (fall) begin
                    next_state = IDLE; // Stay in IDLE if falling
                end else if (bump_left || bump_right) begin
                    next_state = WALK_LEFT; // Switch to walking left
                end else begin
                    next_state = WALK_RIGHT; // Continue walking right
                end
            end
            default: begin
                next_state = IDLE; // Default state
            end
        endcase
    end

    // Output logic
    always @(*) begin
        case (current_state)
            IDLE: begin
                walk_left = 0;
                walk_right = 0;
                aaah = fall;
            end
            WALK_LEFT: begin
                walk_left = 1;
                walk_right = 0;
                aaah = fall;
            end
            WALK_RIGHT: begin
                walk_left = 0;
                walk_right = 1;
                aaah = fall;
            end
            default: begin
                walk_left = 0;
                walk_right = 0;
                aaah = 0;
            end
        endcase
    end

endmodule

module top_module (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);

    // Define states
    localparam IDLE = 2'b00;
    localparam FALLING = 2'b01;
    localparam WALK_LEFT = 2'b10;
    localparam WALK_RIGHT = 2'b11;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
        end else begin
            current_state <= next_state;
            case (current_state)
                IDLE: begin
                    walk_left <= (next_state == WALK_LEFT);
                    walk_right <= (next_state == WALK_RIGHT);
                    aaah <= 0;
                end
                FALLING: begin
                    walk_left <= (next_state == WALK_LEFT);
                    walk_right <= (next_state == WALK_RIGHT);
                    aaah <= 1;
                end
                WALK_LEFT: begin
                    walk_left <= 1;
                    walk_right <= 0;
                    aaah <= 0;
                end
                WALK_RIGHT: begin
                    walk_left <= 0;
                    walk_right <= 1;
                    aaah <= 0;
                end
                default: begin
                    walk_left <= 0;
                    walk_right <= 0;
                    aaah <= 0;
                end
            endcase
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (bump_left || bump_right) begin
                    next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                end
            end
            FALLING: begin
                if (ground) begin
                    next_state = (walk_left) ? WALK_LEFT : WALK_RIGHT;
                end
            end
            WALK_LEFT: begin
                if (bump_left || bump_right) begin
                    next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                end
            end
            WALK_RIGHT: begin
                if (bump_left || bump_right) begin
                    next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule

module top_module(
