    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            thousands <= 4'b0000;
            ena <= 4'b0000;
        end else begin
            // Increment the least significant digit first
            ones <= ones + 1;
            if (ones == 4'b1010) begin // 9 in binary
                ones <= 4'b0000;
                tens <= tens + 1;
            end

            if (tens == 4'b1010) begin // 9 in binary
                tens <= 4'b0000;
                hundreds <= hundreds + 1;
            end

            if (hundreds == 4'b1010) begin // 9 in binary
                hundreds <= 4'b0000;
                thousands <= thousands + 1;
            end

            // Set enable signals for upper three digits
            ena[0] <= (thousands != 4'b1010);
            ena[1] <= (thousands != 4'b1010 || hundreds != 4'b1010);
            ena[2] <= (thousands != 4'b1010 || hundreds != 4'b1010 || tens != 4'b1010);
        end
    end

    assign q = {thousands, hundreds, tens, ones};
endmodule

