    reg [1:0] state = IDLE;

    // Define the next state logic
    always @(posedge ring or posedge vibrate_mode) begin
        case (state)
            IDLE: begin
                if (vibrate_mode == 1) begin
                    state <= MOTOR_ON;
                end else if (ring == 1) begin
                    state <= RINGER_ON;
                end
            end
            RINGER_ON: begin
                if (ring == 0) begin
                    state <= IDLE;
                end
            end
            MOTOR_ON: begin
                if (vibrate_mode == 0) begin
                    state <= IDLE;
                end
            end
        endcase
    end

    // Define the output logic
    always @(posedge ring or posedge vibrate_mode) begin
        case (state)
            RINGER_ON: begin
                ringer <= 1;
                motor <= 0;
            end
            MOTOR_ON: begin
                ringer <= 0;
                motor <= 1;
            end
            default: begin
                ringer <= 0;
                motor <= 0;
            end
        endcase
    end

endmodule

