module top_module (
    input clk,
    input areset,
    input x,
    output z
);

    // Define the state machine states
    localparam IDLE = 1'b0;
    localparam RUNNING = 1'b1;

    // Define the state register
    reg [1:0] state = IDLE;

    // Define the input bit register
    reg [1:0] input_bit = 1'b0;

    // Define the output bit register
    reg [1:0] output_bit = 1'b0;

    // Define the sign bit register
    reg sign = 1'b0;

    // Define the output bit counter
    reg [1:0] output_bit_count = 2'b00;

    // Define the output bit register for the 2's complement
    reg [1:0] two_complement_bit = 1'b0;

    // Define the output bit register for the 2's complement
    reg [1:0] two_complement_bit_count = 2'b00;

    // Define the output bit register for the 2's complement
    reg [1:0] two_complement_bit_count_temp = 2'b00;

    // Define the output bit register for the 2's complement
    reg [1:0] output_z = 1'b0;

    always @(posedge clk) begin
        if (areset) begin
            state <= IDLE;
            input_bit <= 1'b0;
            output_bit <= 1'b0;
            sign <= 1'b0;
            output_bit_count <= 2'b00;
            two_complement_bit <= 1'b0;
            two_complement_bit_count <= 2'b00;
            two_complement_bit_count_temp <= 2'b00;
            output_z <= 1'b0;
        end else begin
            case (state)
                IDLE: begin
                    if (x) begin
                        state <= RUNNING;
                        input_bit <= x;
                    end
                end
                RUNNING: begin
                    if (x) begin
                        output_bit_count <= output_bit_count + 1;
                        output_bit <= {output_bit[1], input_bit};
                        if (output_bit_count == 2'b11) begin
                            two_complement_bit_count <= output_bit_count;
                            two_complement_bit <= output_bit;
                            sign <= ~sign;
                        end
                    end else begin
                        state <= IDLE;
                        output_bit_count <= 2'b00;
                        output_bit <= 1'b0;
                        two_complement_bit <= 1'b0;
                        two_complement_bit_count <= 2'b00;
                        two_complement_bit_count_temp <= 2'b00;
                        output_z <= 1'b0;
                    end
                end
            endcase
        end
    end

    // Calculate the 2's complement
    always @(posedge clk) begin
        if (areset) begin
            output_z <= 1'b0;
        end else begin
            case (state)
                RUNNING: begin
                    if (two_complement_bit_count == 2'b11) begin
                        output_z <= ~two_complement_bit;
                    end
                end
            endcase
        end
    end

    assign z = output_z;

endmodule

module top_module (
	input clk,
	input [7:0] in,
	input reset,
	output reg [23:0] out_bytes,
	output reg done
);

reg [7:0] byte1, byte2, byte3;
reg [23:0] message;
reg [2:0] state;

always @(posedge clk) begin
	if (reset) begin
		state <= 0;
		done <= 0;
		byte1 <= 0;
		byte2 <= 0;
		byte3 <= 0;
		message <= 0;
	end
	else begin
		case (state)
			0: begin
				if (in[3]) begin
					state <= 1;
					byte1 <= in;
				end
				else begin
					state <= 0;
					byte1 <= 0;
				end
			end
			1: begin
				if (in[3]) begin
					state <= 2;
					byte2 <= in;
				end
				else begin
					state <= 0;
					byte1 <= 0;
					byte2 <= 0;
				end
			end
			2: begin
				if (in[3]) begin
					state <= 3;
					byte3 <= in;
				end
				else begin
					state <= 0;
					byte1 <= 0;
					byte2 <= 0;
					byte3 <= 0;
				end
			end
			3: begin
				if (in[3]) begin
					done <= 1;
					message <= {byte1, byte2, byte3};
				end
				else begin
					done <= 0;
					byte1 <= 0;
					byte2 <= 0;
					byte3 <= 0;
					message <= 0;
				end
			end
			default: begin
				state <= 0;
				byte1 <= 0;
				byte2 <= 0;
				byte3 <= 0;
				done <= 0;
				message <= 0;
			end
		endcase
	end
end

always @(posedge clk) begin
	if (!reset) begin
		out_bytes <= message;
	end
end

