module top_module (
	input clk,
	input x,
	output z
);

	reg q_xor, q_and, q_or; // D flip-flop outputs
	reg q_xor_d, q_and_d, q_or_d; // D flip-flop next state
	wire w_xor, w_and, w_or; // Intermediate signals for XOR, AND, and OR gates

	// D flip-flop for XOR gate
	always @(posedge clk)
	if (rst) q_xor_d <= 1'b0;
	else q_xor_d <= x ^ q_xor;

	// D flip-flop for AND gate
	always @(posedge clk)
	if (rst) q_and_d <= 1'b0;
	else q_and_d <= q_xor & ~x;

	// D flip-flop for OR gate
	always @(posedge clk)
	if (rst) q_or_d <= 1'b0;
	else q_or_d <= q_xor | ~x;

	// Intermediate signals for XOR, AND, and OR gates
	assign w_xor = q_xor ^ q_xor_d;
	assign w_and = q_xor & ~q_and_d;
	assign w_or = q_xor | ~q_or_d;

	// XNOR gate
	assign z = ~(^{w_xor, w_and, w_or});

	// Reset signal
	wire rst = 1'b1; // Assuming rst is active high

	// Assign outputs
	assign q_xor = q_xor_d;
	assign q_and = q_and_d;
	assign q_or = q_or_d;

endmodule

