module top_module(
    input logic mode,
    input logic too_cold,
    input logic too_hot,
    input logic fan_on,
    output logic heater,
    output logic aircon,
    output logic fan
);

    // Define the state machine states
    localparam IDLE = 2'b00;
    localparam HEATING = 2'b01;
    localparam COOLING = 2'b10;
    localparam FAN_ONLY = 2'b11;

    // Define the state machine
    logic [1:0] state, next_state;

    // Define the state machine outputs
    logic heater_on, aircon_on, fan_on_state;

    // Define the state machine logic
    always_comb begin
        // Determine the next state based on the current state and inputs
        case (state)
            IDLE: begin
                if (mode == 1'b1) next_state = HEATING;
                else if (mode == 1'b0) next_state = COOLING;
                else next_state = IDLE;
            end
            HEATING: begin
                if (too_cold == 1'b1) next_state = HEATING;
                else if (mode == 1'b0) next_state = COOLING;
                else next_state = IDLE;
            end
            COOLING: begin
                if (too_hot == 1'b1) next_state = COOLING;
                else if (mode == 1'b1) next_state = HEATING;
                else next_state = IDLE;
            end
            FAN_ONLY: begin
                if (fan_on == 1'b1) next_state = FAN_ONLY;
                else if (mode == 1'b1) next_state = HEATING;
                else if (mode == 1'b0) next_state = COOLING;
                else next_state = IDLE;
            end
            default: next_state = IDLE;
        endcase

        // Determine the outputs based on the current state
        case (state)
            IDLE: begin
                heater_on = 1'b0;
                aircon_on = 1'b0;
                fan_on_state = 1'b0;
            end
            HEATING: begin
                heater_on = 1'b1;
                aircon_on = 1'b0;
                fan_on_state = 1'b1;
            end
            COOLING: begin
                heater_on = 1'b0;
                aircon_on = 1'b1;
                fan_on_state = 1'b1;
            end
            FAN_ONLY: begin
                heater_on = 1'b0;
                aircon_on = 1'b0;
                fan_on_state = 1'b1;
            end
            default: begin
                heater_on = 1'b0;
                aircon_on = 1'b0;
                fan_on_state = 1'b0;
            end
        endcase
    end

    // Assign the outputs
    assign heater = heater_on;
    assign aircon = aircon_on;
    assign fan = fan_on_state;

endmodule

