    output reg Y0,
    output reg z
);

    // Define the state register
    reg [2:0] state;

    // Define the next state and output logic
    always @(posedge clk) begin
        case (state)
            3'd0: begin
                if (x) state <= 3'd1;
                else state <= 3'd0;
                z <= 1'b0;
            end
            3'd1: begin
                if (x) state <= 3'd0;
                else state <= 3'd1;
                z <= 1'b1;
            end
            3'd2: begin
                if (x) state <= 3'd0;
                else state <= 3'd2;
                z <= 1'b0;
            end
            3'd3: begin
                if (x) state <= 3'd2;
                else state <= 3'd3;
                z <= 1'b1;
            end
            3'd4: begin
                if (x) state <= 3'd2;
                else state <= 3'd4;
                z <= 1'b0;
            end
            3'd5: begin
                if (x) state <= 3'd4;
                else state <= 3'd5;
                z <= 1'b1;
            end
            default: begin
                $fatal(1, "Invalid state");
            end
        endcase
        // Assign the next state to the output
        case (state)
            3'd0: Y0 <= 1'b0;
            3'd1: Y0 <= 1'b0;
            3'd2: Y0 <= 1'b0;
            3'd3: Y0 <= 1'b1;
            3'd4: Y0 <= 1'b0;
            3'd5: Y0 <= 1'b1;
            default: begin
                $fatal(1, "Invalid state");
            end
        endcase
    end

    // Initialize the state register
    initial begin
        state <= 3'd0;
