        // Update the state and output based on the current state and input x
        else begin
            case (state)
                3'b000: begin
                    state <= x? 3'b001 : 3'b000;
                    z <= 1'b0;
                end
                3'b001: begin
                    state <= x? 3'b100 : 3'b001;
                    z <= 1'b0;
                end
                3'b010: begin
                    state <= x? 3'b001 : 3'b010;
                    z <= 1'b0;
                end
                3'b011: begin
                    state <= x? 3'b010 : 3'b011;
                    z <= 1'b1;
                end
                3'b100: begin
                    state <= x? 3'b011 : 3'b100;
                    z <= 1'b1;
                end
                default: begin
