    // Define the clock enable logic
    always @(posedge clk) begin
        clk_en = 1'b1;
    end

    // Define the reset logic
    always @(posedge clk) begin
        if (reset) begin
            clk_en = 1'b0;
            counter = 10'd0;
            tc_reg = 1'b0;
