    end

    // Define the counter logic
    always @(posedge clk) begin
        if (clk_en) begin
            if (counter > 1'b0) begin
                counter = counter - 1'b1;
            end
            if (counter == 1'b0) begin
                tc_reg = 1'b1;
            end
        end
    end

