module top_module(
    input  clk,
    input  reset,
    input  data,
    output start_shifting
);

    // Define the states of the finite-state machine
    localparam IDLE = 0;
    localparam FOUND = 1;

    // Define the state register
    reg [1:0] state = IDLE;

    // Define the start_shifting output
    reg start_shifting_reg;

    // Define the counter to track the sequence
    reg [3:0] counter = 0;

    // Define the sequence to search for
    localparam SEQUENCE = 4'd1101;

    // Define the state transitions
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            counter <= 0;
            start_shifting_reg <= 0;
        end else begin
            case (state)
                IDLE: begin
                    if (data) begin
                        counter <= 1;
                    end else begin
                        counter <= 0;
                    end
                end
                FOUND: begin
                    start_shifting_reg <= 1;
                end
            endcase
        end
    end

    // Update the state based on the current state and the input data
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
        end else begin
            case (state)
                IDLE: begin
                    if (counter == SEQUENCE) begin
                        state <= FOUND;
                    end else if (data) begin
                        counter <= counter + 1;
                    end else begin
                        counter <= 0;
                    end
                end
                FOUND: begin
