    reg [2:0] state = IDLE;
    reg [2:0] count = 3'b0;

    // Define the reset signal
    reg reset = 1'b0;

    always @(posedge clk) begin
        reset <= 1'b0;
        if (!reset) begin
            if (a) begin
                state <= COUNTING;
                count <= 3'b0;
