            else begin
                state <= IDLE;
                count <= 3'b0;
            end
        end
        else begin
            case (state)
                IDLE: begin
                    if (a) begin
                        state <= COUNTING;
                        count <= 3'b0;
                    end
                end
                COUNTING: begin
                    if (count == 3'd4) begin
                        state <= DONE;
                    end
                    else begin
                        count <= count + 1;
