                end
                DONE: begin
                    if (a) begin
                        state <= RESET;
                    end
                    else begin
                        state <= IDLE;
                    end
                end
                RESET: begin
                    state <= IDLE;
                end
            endcase
        end
    end

    // Assign the output
    assign q = state;
