module top_module(
    input clk,
    input reset,
    output reg [4:0] q
);

    // Define the taps for the LFSR
    parameter TAPS = 5'b10101;

    // Initialize the LFSR state
    reg [4:0] state = 5'd1;

    // Clock and reset logic
    always @(posedge clk)
    begin
        if (reset)
            state <= 5'd1;
        else
            begin
                // Shift the state
                state <= {state[4], state[3], state[2], state[1], state[0]};

                // Apply the taps
                for (int i = 0; i < 5; i++)
                    if (TAPS[i])
                        state[i] = ~state[i] ^ state[4];
            end
    end

    // Output the current state
    assign q = state;

endmodule

module top_module(
    input clk,
    input reset,
    output reg [4:0] q
);

    // Define the taps for the Galois LFSR
    parameter TAPS = 5'b10101;

    // Initialize the LFSR state to all zeros
    reg [4:0] state = 5'b00000;

    // Define the next state function
    function automatic reg [4:0] next_state(reg [4:0] state);
        reg [4:0] next_state = state;
        for (int i = 0; i < 5; i++) begin
            if (TAPS[4 - i] == 1) begin
                next_state[i] = next_state[i] ^ state[4];
            end
        end
    endfunction

    // Clock edge sensitive, active-high reset
    always @(posedge clk)
        if (reset) begin
            state <= 5'b00001;
        end else begin
            state <= next_state(state);
        end

    // Output the current state
    assign q = state;

endmodule

