module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output logic done
);

    // State machine states
    enum logic [1:0] {IDLE, FOUND_FIRST_BYTE, FOUND_SECOND_BYTE, FOUND_THIRD_BYTE} state;

    // Register to store the current byte
    logic [7:0] current_byte;

    // Register to store the number of bytes received since the last message start
    logic [2:0] byte_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= IDLE;
            byte_count <= 3'd0;
            done <= 1'b0;
        end
        else begin
            case (state)
                IDLE: begin
                    if (in[3]) begin
                        state <= FOUND_FIRST_BYTE;
                        byte_count <= 1;
                    end
                end
                FOUND_FIRST_BYTE: begin
                    if (in[3]) begin
                        state <= FOUND_SECOND_BYTE;
                        byte_count <= 2;
                    end
                    else begin
                        state <= IDLE;
                        byte_count <= 3'd0;
                    end
                end
                FOUND_SECOND_BYTE: begin
                    if (in[3]) begin
                        state <= FOUND_THIRD_BYTE;
                        byte_count <= 3;
                    end
                    else begin
                        state <= IDLE;
                        byte_count <= 3'd0;
                    end
                end
                FOUND_THIRD_BYTE: begin
                    if (byte_count == 3) begin
                        done <= 1;
                        state <= IDLE;
                        byte_count <= 3'd0;
                    end
                    else begin
                        state <= IDLE;
                        byte_count <= 3'd0;
                    end
                end
            endcase
        end
    end

    // Assign the current byte to a register
    always @(posedge clk or posedge reset) begin
        if (!reset) begin
            current_byte <= in;
        end
    end

endmodule

module top_module (
    input clk,
    input [7:0] in,
    input reset,
    output done
);

reg [7:0] buffer [2:0]; // buffer to store the last 3 bytes
reg [7:0] buffer_ptr; // pointer to the current position in the buffer
reg [7:0] last_byte; // last byte received
reg done;

always @(posedge clk)
begin
    if (reset)
        done <= 1'b0;
    else
    begin
        // shift in the new byte
        buffer_ptr <= buffer_ptr + 1;
        buffer[buffer_ptr] <= in;

        // check if we have a valid message
        if (buffer_ptr == 3 && buffer[0][3] == 1)
        begin
            // check if we have a complete message
            if (buffer[1][3] == 1 && buffer[2][3] == 1)
                done <= 1'b1;
            else
                done <= 1'b0;
        end
        else
        begin
            // if we don't have a complete message, reset the buffer
            buffer_ptr <= 0;
            done <= 1'b0;
        end
    end
end

endmodule

module top_module (
    input clk,
    input resetn,
    input x,
    input y,
    output f,
    output g
);

reg [1:0] state;
reg [1:0] x_count;
reg [1:0] y_count;
reg f;
reg g;

always @ (posedge clk or negedge resetn) begin
    if (!resetn) begin
        state <= 2'b00;
        x_count <= 2'b00;
        y_count <= 2'b00;
        f <= 1'b0;
        g <= 1'b0;
    end
end

always @ (posedge clk) begin
    case (state)
        2'b00: begin
            if (!resetn) begin
                state <= 2'b00;
                x_count <= 2'b00;
                y_count <= 2'b00;
                f <= 1'b0;
                g <= 1'b0;
            end else begin
                f <= 1'b1;
                state <= 2'b01;
                x_count <= 2'b00;
            end
        end
        2'b01: begin
            if (x == 1'b1) begin
                x_count <= x_count + 1;
                if (x_count == 2'b11) begin
                    state <= 2'b10;
                    x_count <= 2'b00;
                end
            end else begin
                x_count <= 2'b00;
            end
        end
        2'b10: begin
            if (x == 1'b1) begin
                x_count <= x_count + 1;
                if (x_count == 2'b11) begin
                    state <= 2'b11;
                    x_count <= 2'b00;
                end
            end else begin
                x_count <= 2'b00;
            end
        end
        2'b11: begin
            if (y == 1'b1) begin
                y_count <= y_count + 1;
                if (y_count == 2'b11) begin
                    g <= 1'b1;
                end
            end else begin
                y_count <= 2'b00;
            end
            if (y_count == 2'b00) begin
                g <= 1'b0;
            end
        end
    endcase
end

endmodule

module top_module (
