	// Flip-flop for p
	reg p_ff;
	always @(posedge clock)
		if (!rst)
			p_ff <= #1 a;
		else
			p_ff <= #1 p_ff;

	// Flip-flop for q
	reg q_ff;
	always @(posedge clock)
		if (!rst)
			q_ff <= #1 a;
		else
			q_ff <= #1 (p_ff & ~q_ff);

	// Assign outputs
	assign p = p_ff;
	assign q = q_ff;

endmodule

