    output reg [7:0] out_byte,
    output reg done
);

    reg [7:0] data_byte = 0;
    reg [8:0] bit_count = 0;
    reg start_bit_received = 0;
    reg stop_bit_received = 0;

    always @(posedge clk)
    begin
        if (reset)
            begin
                data_byte = 0;
                bit_count = 0;
                start_bit_received = 0;
                stop_bit_received = 0;
                done = 0;
            end
        else
            begin
                case (bit_count)
                    0: begin
                        if (in)
                            start_bit_received = 1;
                    end
                    1: begin
                        data_byte[0] = in;
                        bit_count = bit_count + 1;
                    end
                    2: begin
                        data_byte[1] = in;
                        bit_count = bit_count + 1;
                    end
                    3: begin
                        data_byte[2] = in;
                        bit_count = bit_count + 1;
                    end
                    4: begin
                        data_byte[3] = in;
                        bit_count = bit_count + 1;
                    end
                    5: begin
                        data_byte[4] = in;
                        bit_count = bit_count + 1;
                    end
                    6: begin
                        data_byte[5] = in;
                        bit_count = bit_count + 1;
                    end
                    7: begin
                        data_byte[6] = in;
                        bit_count = bit_count + 1;
                    end
                    8: begin
                        data_byte[7] = in;
                        bit_count = bit_count + 1;
                        if (in)
                            stop_bit_received = 1;
                    end
                    9: begin
                        if (in)
                            done = 1;
                        else
                            bit_count = 0;
                    end
                    default: begin
                        if (in)
                            bit_count = 0;
                    end
                endcase
            end
    end

