module top_module(
    input d,
    input done_counting,
    input ack,
    input [9:0] state,    // 10-bit one-hot current state
    output B3_next,
    output S_next,
    output S1_next,
    output Count_next,
    output Wait_next,
    output done,
    output counting,
    output shift_ena
 );

// Next-state logic equations
assign B3_next = state[8] & state[7] & state[6] & state[5] & state[4] & state[3] & state[2] & state[1] & state[0] & (state[9] | d);
assign S_next = state[8] & state[7] & state[6] & state[5] & state[4] & state[3] & state[2] & (state[1] | d);
assign S1_next = state[8] & state[7] & state[6] & state[5] & state[4] & state[3] & (state[2] | d);
assign Count_next = state[8] & state[7] & state[6] & state[5] & state[4] & (state[3] | (state[2] & done_counting));
assign Wait_next = state[8] & state[7] & state[6] & state[5] & (state[4] | (state[3] & done_counting & ack));

// Output logic equations
assign done = (state[9] | state[8] | state[7] | state[6] | state[5] | state[4] | state[3] | state[2] | state[1] | state[0]);
assign counting = state[2] | state[1] | state[0];
assign shift_ena = state[3] | state[2] | state[1] | state[0];

