	// Behavioral description of the thermostat
	always_comb begin
		// Heating mode
		if (mode == 1) begin
			heater <= too_cold;
			aircon <= 0;
			fan <= 1;
		end

		// Cooling mode
		else if (mode == 0) begin
			heater <= 0;
			aircon <= too_hot;
			fan <= 1;
		end

		// Fan on regardless of mode
		else begin
			heater <= 0;
			aircon <= 0;
			fan <= fan_on;
		end
	end

endmodule

