module top_module(
	input clk,
	input reset,
	output reg [4:0] q);

	// Define the taps for the LFSR
	parameter TAPS = 5'b10101;

	// Initialize the LFSR state
	reg [4:0] state = 5'd1;

	// Clock and reset logic
	always @(posedge clk) begin
		if (reset) begin
			state <= 5'd1; // Reset to 1
		end else begin
			// Shift the state
			state <= {state[4], state[3], state[2], state[1], state[0]};

			// Apply the taps
			for (int i = 0; i < 5; i++) begin
				if (TAPS[i]) begin
					state[i] = ~state[i] ^ state[4]; // XOR with the output bit
				end
			end
		end
	end

	// Output the current state
	assign q = state;

endmodule

