    if (!resetn)
        state <= A;
    else
        state <= next_state;
end

always @(*) begin
    next_state = state;
    g = 4'b0000;

    case (state)
        A: begin
            if (r == 4'b0000)
                next_state = A;
            else if (r == 4'b0001)
                next_state = B;
            else if (r == 4'b0010)
                next_state = C;
            else if (r == 4'b0011)
                next_state = D;
        end
        B: begin
            if (r == 4'b0001 && g[1])
                next_state = B;
            else
                next_state = A;
        end
        C: begin
            if (r == 4'b0010 && g[2])
                next_state = C;
            else
                next_state = A;
        end
        D: begin
            next_state = A;
        end
        default: next_state = A;
    endcase

    case (state)
        A: begin
            if (r == 4'b0001)
                g[1] = 1;
            else if (r == 4'b0010)
                g[2] = 1;
            else if (r == 4'b0011)
                g[3] = 1;
        end
        B: begin
            if (r == 4'b0001)
                g[1] = 1;
        end
        C: begin
            if (r == 4'b0010)
                g[2] = 1;
        end
        default: ;
    endcase
end

