module top_module(
    input wire clk,
    input wire reset,
    input wire data,
    output wire [3:0] count,
    output reg counting,
    output reg done,
    input wire ack
);

    // State machine states
    enum logic [2:0] {IDLE, SHIFTING, COUNTING, DONE} state;

    // Shift register for the delay value
    reg [3:0] delay;

    // Counter value
    reg [3:0] counter;

    // Current remaining time
    reg [3:0] remaining_time;

    // Flag to indicate if the start sequence has been detected
    reg start_detected;

    // Flag to indicate if the delay value has been received
    reg delay_received;

    // Flag to indicate if the counter has finished counting
    reg counter_finished;

    // Flag to indicate if the user has acknowledged the timer
    reg ack_received;

    // Reset the state machine and flags on reset
    always @(posedge reset)
        state <= IDLE;
    always @(posedge reset)
        start_detected <= 0;
    always @(posedge reset)
        delay_received <= 0;
    always @(posedge reset)
        counter_finished <= 0;
    always @(posedge reset)
        ack_received <= 0;

    // Shift in the delay value when the start sequence is detected
    always @(posedge clk)
    begin
        if (reset)
            delay <= 0;
        else if (state == IDLE && data == 4'b1101)
            state <= SHIFTING;
    end

    always @(posedge clk)
    begin
        if (reset)
            delay <= 0;
        else if (state == SHIFTING)
        begin
            delay <= {delay[3:1], data};
            state <= COUNTING;
        end
    end

    // Count for the specified duration
    always @(posedge clk)
    begin
        if (reset)
            counter <= 0;
        else if (state == COUNTING)
        begin
            counter <= counter + 1;
            if (counter == (delay + 1) * 1000)
                counter_finished <= 1;
        end
    end

    // Update the remaining time
    always @(posedge clk)
    begin
        if (reset)
            remaining_time <= 0;
        else if (state == COUNTING)
        begin
            if (counter == (delay + 1) * 1000)
                remaining_time <= 0;
            else if (counter < (delay + 1) * 1000)
                remaining_time <= delay - counter / 1000;
        end
    end

    // Assert the done signal when the counter has finished counting
    always @(posedge clk)
    begin
        if (reset)
            done <= 0;
        else if (state == COUNTING && counter_finished)
            done <= 1;
    end

    // Assert the counting signal when the state machine is counting
    always @(posedge clk)
    begin
        if (reset)
            counting <= 0;
        else if (state == COUNTING)
            counting <= 1;
    end

    // Assert the ack_received flag when the user acknowledges the timer
    always @(posedge clk)
    begin
        if (reset)
            ack_received <= 0;
        else if (done && ack)
            ack_received <= 1;
    end

    // Reset the state machine and flags when the user acknowledges the timer
    always @(posedge clk)
    begin
        if (reset)
            state <= IDLE;
        else if (done && ack)
            state <= IDLE;
    end

    // Output the current remaining time
    assign count = remaining_time;

endmodule

module top_module(
    input wire clk,
    input wire reset,
    input wire data,
    output wire [3:0] count,
    output reg counting,
    output reg done,
    input wire ack
);

    // State machine states
    enum logic [2:0] { IDLE, SHIFTING, COUNTING, DONE } state;

    // Shift register for the delay value
    reg [3:0] delay;

    // Counter value
    reg [3:0] counter;

    // Current remaining time
    reg [3:0] remaining_time;

    // Flag to indicate if the start sequence has been detected
    reg start_detected;

    // Flag to indicate if the delay value has been received
    reg delay_received;

    // Flag to indicate if the counter has finished counting
    reg counter_finished;

    // Flag to indicate if the user has acknowledged the timer
    reg ack_received;

    // Reset the state machine and flags on reset
    always @(posedge reset)
        state <= IDLE;
    always @(posedge reset)
        start_detected <= 0;
    always @(posedge reset)
        delay_received <= 0;
    always @(posedge reset)
        counter_finished <= 0;
    always @(posedge reset)
        ack_received <= 0;

    // Shift in the delay value when the start sequence is detected
    always @(posedge clk)
    begin
        if (reset)
            delay <= 0;
        else if (state == IDLE && data == 4'b1101)
            state <= SHIFTING;
    end

    always @(posedge clk)
    begin
        if (reset)
            delay <= 0;
        else if (state == SHIFTING)
        begin
            delay <= {delay[3:1], data};
            state <= COUNTING;
        end
    end

    // Count for the specified duration
    always @(posedge clk)
    begin
        if (reset)
            counter <= 0;
        else if (state == COUNTING)
        begin
            counter <= counter + 1;
            if (counter == (delay + 1) * 1000)
                counter_finished <= 1;
        end
    end

    // Update the remaining time
    always @(posedge clk)
    begin
        if (reset)
            remaining_time <= 0;
        else if (state == COUNTING)
        begin
            if (counter == (delay + 1) * 1000)
                remaining_time <= 0;
            else if (counter < (delay + 1) * 1000)
                remaining_time <= delay - counter / 1000;
        end
    end

    // Assert the done signal when the counter has finished counting
    always @(posedge clk)
    begin
        if (reset)
            done <= 0;
        else if (state == COUNTING && counter_finished)
            done <= 1;
    end

    // Assert the counting signal when the state machine is counting
    always @(posedge clk)
    begin
        if (reset)
            counting <= 0;
        else if (state == COUNTING)
            counting <= 1;
    end

    // Assert the ack_received flag when the user acknowledges the timer
    always @(posedge clk)
    begin
        if (reset)
            ack_received <= 0;
        else if (done && ack)
            ack_received <= 1;
    end

    // Reset the state machine and flags when the user acknowledges the timer
    always @(posedge clk)
    begin
        if (reset)
            state <= IDLE;
        else if (done && ack)
            state <= IDLE;
    end

    // Output the current remaining time
    assign count = remaining_time;

endmodule

module top_module(
    input clk,
    input areset, 

    input predict_valid,
    input [6:0] predict_pc,
    output reg predict_taken, 
    output reg [6:0] predict_history,

    input train_valid,
    input train_taken,
    input train_mispredicted,
    input [6:0] train_history, 
    input [6:0] train_pc
);

    parameter PHT_SIZE = 128;
    parameter HISTORY_BITS = 7;

    reg [HISTORY_BITS-1:0] global_branch_history;
    reg [HISTORY_BITS-1:0] pht [0:PHT_SIZE-1];
    reg [1:HISTORY_BITS-1] pht_state [0:PHT_SIZE-1];

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            global_branch_history <= 0;
            for (int i = 0; i < PHT_SIZE; i++) begin
                pht[i] <= 0;
                pht_state[i] <= 2'b00;
            end
        end else begin
            if (train_valid) begin
                int index;
                index = predict_pc ^ global_branch_history;
                pht[index] <= train_history;
                if (train_mispredicted) begin
                    global_branch_history <= train_history;
                end
            end

            if (predict_valid) begin
                int index;
                index = predict_pc ^ global_branch_history;
                predict_taken <= (pht_state[index] == 2'b11);
                predict_history <= pht[index];
                pht_state[index] <= (train_valid) ? 2'b01 : (predict_taken) ? 2'b10 : 2'b00;
            end
        end
    end

endmodule

module top_module (
	input clk,
	input areset,
	input bump_left,
	input bump_right,
	input ground,
	input dig,
	output reg walk_left,
	output reg walk_right,
	output reg aaah,
	output reg digging
);

	// State definitions
	localparam IDLE = 3'b000;
	localparam WALK_LEFT = 3'b001;
	localparam WALK_RIGHT = 3'b010;
	localparam FALLING = 3'b011;
	localparam DIGGING = 3'b100;

	reg [2:0] current_state, next_state;
	reg [4:0] fall_counter;

	always @(posedge clk or posedge areset) begin
		if (areset) begin
			current_state <= WALK_LEFT;
			fall_counter <= 5'd0;
			walk_left <= 1'b1;
			walk_right <= 1'b0;
			aaah <= 1'b0;
			digging <= 1'b0;
		end else begin
			current_state <= next_state;
			case (current_state)
				IDLE: begin
					walk_left <= 1'b1;
					walk_right <= 1'b0;
					aaah <= 1'b0;
					digging <= 1'b0;
				end
				WALK_LEFT: begin
					walk_left <= 1'b1;
					walk_right <= 1'b0;
					aaah <= 1'b0;
					digging <= 1'b0;
					if (bump_left || bump_right) begin
						next_state <= WALK_RIGHT;
					end else if (!ground) begin
						next_state <= FALLING;
					end else if (dig && ground) begin
						next_state <= DIGGING;
					end
				end
				WALK_RIGHT: begin
					walk_left <= 1'b0;
					walk_right <= 1'b1;
					aaah <= 1'b0;
					digging <= 1'b0;
					if (bump_left || bump_right) begin
						next_state <= WALK_LEFT;
					end else if (!ground) begin
						next_state <= FALLING;
					end else if (dig && ground) begin
						next_state <= DIGGING;
					end
				end
				FALLING: begin
					walk_left <= 1'b0;
					walk_right <= 1'b0;
					aaah <= 1'b1;
					digging <= 1'b0;
					fall_counter <= fall_counter + 1;
					if (fall_counter >= 5'd20) begin
						next_state <= IDLE;
					end else if (ground) begin
						next_state <= WALK_LEFT;
					end
				end
				DIGGING: begin
					walk_left <= 1'b0;
					walk_right <= 1'b0;
					aaah <= 1'b0;
					digging <= 1'b1;
					if (!ground) begin
						next_state <= FALLING;
					end else if (!dig) begin
						next_state <= WALK_LEFT;
					end
				end
				default: begin
					current_state <= IDLE;
				end
			endcase
		end
	end

endmodule

module top_module(
    input clk,
    input load,
    input [255:0] data,
    output reg [255:0] q
);

    // Define the clock and reset signals
    reg clk_r = 0;
    reg reset = 1;

    // Define the game state
    reg [255:0] state = 0;

    // Define the clock and reset timing
    always @(posedge clk)
        if (reset)
            reset <= 0;
        else
            clk_r <= clk;

    // Define the game logic
    always @(posedge clk_r)
    begin
        if (load)
            state <= data;
        else
        begin
            // Create a copy of the current state
            reg [255:0] next_state = state;

            // Iterate over each cell in the grid
            for (int i = 0; i < 256; i = i + 1)
            begin
                // Calculate the row and column of the current cell
                int row = i / 16;
                int col = i % 16;

                // Calculate the number of alive neighbours
                int alive_neighbours = 0;
                for (int j = -1; j <= 1; j = j + 1)
                begin
                    for (int k = -1; k <= 1; k = k + 1)
                    begin
                        // Calculate the row and column of the neighbour
                        int neighbour_row = (row + j + 16) % 16;
                        int neighbour_col = (col + k + 16) % 16;

                        // Check if the neighbour is alive
                        if (state[(neighbour_row * 16 + neighbour_col) * 4 + 0] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 1] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 2] == 1 ||
                            state[(neighbour_row * 16 + neighbour_col) * 4 + 3] == 1)
                            alive_neighbours = alive_neighbours + 1;
                    end
                end

                // Update the cell state based on the number of alive neighbours
                case (alive_neighbours)
                    0: next_state[i] = 0;
                    1: next_state[i] = 0;
                    2: next_state[i] = state[i];
                    3: next_state[i] = 1;
                    default: next_state[i] = 0;
                endcase
            end

            // Update the game state
            state <= next_state;
        end
    end

    // Assign the game state to the output
    assign q = state;

endmodule

