    output reg [7:0] ss);

    reg [3:0] bcd_ss;
    reg [3:0] bcd_mm;
    reg [3:0] bcd_hh;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            pm <= 0;
            bcd_ss <= 8'd0;
            bcd_mm <= 8'd0;
            bcd_hh <= 8'd12;
        end else begin
            if (ena) begin
                bcd_ss <= bcd_ss + 1;
                if (bcd_ss == 8'd60) begin
                    bcd_ss <= 8'd0;
                    bcd_mm <= bcd_mm + 1;
                    if (bcd_mm == 8'd60) begin
                        bcd_mm <= 8'd0;
                        bcd_hh <= bcd_hh + 1;
                        if (bcd_hh == 8'd13) begin
                            bcd_hh <= 8'd1;
                        end
                    end
                end
            end
        end
    end

    always @(posedge clk) begin
        if (bcd_hh > 8'd12) begin
            pm <= 1;
            hh <= {4'b0, bcd_hh - 8'd12};
        end else begin
            pm <= 0;
            hh <= {4'b0, bcd_hh};
        end
        mm <= {4'b0, bcd_mm};
        ss <= {4'b0, bcd_ss};
    end

endmodule

module top_module(
    input clk,
    input reset,
    input ena,
    output reg pm,
    output reg [7:0] hh,
    output reg [7:0] mm,
    output reg [7:0] ss);

    // BCD counters for hours, minutes, and seconds
    reg [3:0] bcd_hh;
    reg [3:0] bcd_mm;
    reg [3:0] bcd_ss;

    // Clock domain for BCD counter updates
    always @(posedge clk) begin
        if (reset) begin
            // Reset BCD counters to initial values
            bcd_hh <= 8'd0;
            bcd_mm <= 8'd0;
            bcd_ss <= 8'd0;
            // Set PM indicator to AM
            pm <= 0;
        end else begin
            // Increment BCD counter for seconds
            bcd_ss <= bcd_ss + 1;

            // Handle overflow for seconds counter
            if (bcd_ss == 8'd60) begin
                bcd_ss <= 8'd0;
                bcd_mm <= bcd_mm + 1;
            end

            // Handle overflow for minutes counter
            if (bcd_mm == 8'd60) begin
                bcd_mm <= 8'd0;
                bcd_hh <= bcd_hh + 1;
            end

            // Handle overflow for hours counter
            if (bcd_hh == 8'd24) begin
                bcd_hh <= 8'd0;
            end
        end
    end

    // Convert BCD counters to human-readable time format
    always @(posedge clk) begin
        // Set PM indicator based on hours value
        if (bcd_hh > 8'd12) begin
            pm <= 1;
            hh <= {4'b0, bcd_hh - 8'd12};
        end else begin
            pm <= 0;
            hh <= {4'b0, bcd_hh};
        end

        // Convert BCD counters to BCD digits
        mm <= {4'b0, bcd_mm};
        ss <= {4'b0, bcd_ss};
    end

endmodule

module top_module (
	input clk,
	input areset,
	input bump_left,
	input bump_right,
	input ground,
	output reg walk_left,
	output reg walk_right,
	output reg aaah
);

reg [1:0] state;
reg [1:0] next_state;

always @(posedge clk or posedge areset) begin
	if (areset) begin
		state <= 2'b00;
		walk_left <= 1'b0;
		walk_right <= 1'b0;
		aaah <= 1'b0;
	end else begin
		state <= next_state;
		case (state)
			2'b00: begin
				if (bump_left) begin
					next_state = 2'b01;
					walk_left <= 1'b0;
					walk_right <= 1'b1;
					aaah <= 1'b0;
				end else if (bump_right) begin
					next_state = 2'b10;
					walk_left <= 1'b1;
					walk_right <= 1'b0;
					aaah <= 1'b0;
				end else begin
					next_state = 2'b00;
					walk_left <= (ground)? 1'b0 : 1'b1;
					walk_right <= (ground)? 1'b1 : 1'b0;
					aaah <= 1'b0;
				end
			end
			2'b01: begin
				if (ground) begin
					next_state = 2'b01;
					walk_left <= 1'b0;
					walk_right <= 1'b1;
					aaah <= 1'b1;
				end else begin
					next_state = 2'b01;
					walk_left <= 1'b0;
					walk_right <= 1'b1;
					aaah <= 1'b0;
				end
			end
			2'b10: begin
				if (ground) begin
					next_state = 2'b10;
					walk_left <= 1'b1;
					walk_right <= 1'b0;
					aaah <= 1'b1;
				end else begin
					next_state = 2'b10;
					walk_left <= 1'b1;
					walk_right <= 1'b0;
					aaah <= 1'b0;
				end
			end
			default: begin
				next_state = 2'b00;
				walk_left <= 1'b0;
				walk_right <= 1'b0;
				aaah <= 1'b0;
			end
		endcase
	end
end

endmodule

module top_module (
    input clk,
    input areset,
    input bump_left,
    input bump_right,
    input ground,
    output reg walk_left,
    output reg walk_right,
    output reg aaah
);

    // Define states
    localparam IDLE = 2'b00;
    localparam FALLING = 2'b01;
    localparam WALK_LEFT = 2'b10;
    localparam WALK_RIGHT = 2'b11;

    reg [1:0] current_state, next_state;

    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
        end else begin
            current_state <= next_state;
            case (current_state)
                IDLE: begin
                    if (!ground) begin
                        next_state = FALLING;
                    end else if (bump_left || bump_right) begin
                        next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                    end
                end
                FALLING: begin
                    if (ground) begin
                        next_state = (walk_left) ? WALK_LEFT : WALK_RIGHT;
                    end
                end
                WALK_LEFT: begin
                    if (bump_left || bump_right) begin
                        next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                    end
                end
                WALK_RIGHT: begin
                    if (bump_left || bump_right) begin
                        next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                    end
                end
                default: begin
                    next_state = IDLE;
                end
            endcase
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            IDLE: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (bump_left) begin
                    next_state = WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                end
            end
            FALLING: begin
                if (ground) begin
                    next_state = WALK_LEFT;
                end
            end
            WALK_LEFT: begin
                if (bump_left) begin
                    next_state = WALK_RIGHT;
                end else if (bump_right) begin
                    next_state = WALK_LEFT;
                end
            end
            WALK_RIGHT: begin
                if (bump_left) begin
                    next_state = WALK_LEFT;
                end else if (bump_right) begin
                    next_state = WALK_RIGHT;
                end
            end
            default: begin
                next_state = IDLE;
            end
        endcase
    end

endmodule

