);

    reg [3:0] ones, tens, hundreds, thousands;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            ones <= 4'b0000;
            tens <= 4'b0000;
            hundreds <= 4'b0000;
            thousands <= 4'b0000;
            ena <= 4'b0000;
        end else begin
            // Increment the least significant digit first
            ones <= ones + 1;
            if (ones == 4'b1010) begin // 9 in binary
                ones <= 4'b0000;
                tens <= tens + 1;
            end

            if (tens == 4'b1010) begin // 9 in binary
